module lcd_pixel_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input signed [17:0] vertical_t [0:7],\n    input signed [17:0] vertical_m [0:7],\n    input signed [17:0] vertical_a [0:7],\n    input [7:0] vertical_valid,\n    input signed [17:0] horizontal_t [0:7],\n    input signed [17:0] horizontal_m [0:7],\n    input signed [17:0] horizontal_a [0:7],\n    input [7:0] horizontal_valid,\n    output reg [5:0] count,\n    output reg done\n);\n    \n    // FSM States\n    localparam IDLE = 1'b0;\n    localparam COMPUTE = 1'b1;\n    \n    reg state;\n    reg [5:0] counter;\n    reg [5:0] pixel_count;\n    \n    // Index extraction\n    wire [2:0] v_idx = counter[5:3];\n    wire [2:0] h_idx = counter[2:0];\n    \n    // Valid flags for current indices\n    wire v_valid = vertical_valid[v_idx];\n    wire h_valid = horizontal_valid[h_idx];\n    \n    // Signed parameters for vertical\n    wire signed [17:0] tv = vertical_t[v_idx];\n    wire signed [17:0] mv = vertical_m[v_idx];\n    wire signed [17:0] av = vertical_a[v_idx];\n    \n    // Signed parameters for horizontal\n    wire signed [17:0] th = horizontal_t[h_idx];\n    wire signed [17:0] mh = horizontal_m[h_idx];\n    wire signed [17:0] ah = horizontal_a[h_idx];\n    \n    // Intermediate signals\n    wire signed [17:0] d = tv - th;\n    wire signed [17:0] k = av - ah;\n    wire signed [17:0] lower = k - mv;\n    wire signed [17:0] upper = k + mh;\n    \n    // Condition check\n    wire condition = (d > lower) && (d < upper);\n    wire increment = v_valid && h_valid && condition;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            counter <= 6'd0;\n            pixel_count <= 6'd0;\n            count <= 6'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    counter <= 6'd0;\n                    pixel_count <= 6'd0;\n                    count <= 6'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end else begin\n                        state <= IDLE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (counter < 6'd63) begin\n                        counter <= counter + 6'd1;\n                    end else begin\n                        state <= IDLE;\n                    end\n                    \n                    if (increment) begin\n                        pixel_count <= pixel_count + 6'd1;\n                    end\n                    \n                    count <= pixel_count + (increment ? 6'd1 : 6'd0);\n                    done <= (counter == 6'd63);\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule